// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    uint256 constant FUNDED = 100 ether;

    function setUp() public {
        c = new SimpleWallet();
        vm.deal(address(c), FUNDED);
    }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        // owner is address(this) (deployer); withdraw sends to msg.sender = owner,
        // so the test contract must accept ETH (receive above).
        uint256 v = bound(amount, 1, FUNDED - 1);

        vm.prank(address(this));
        c.withdraw(v);

        // After withdrawing exactly v (< full balance), the contract must retain
        // balance - v; the mutant drains the entire balance instead.
        assertTrue(address(c).balance == FUNDED - v);
    }
}
